.article_list ul {
    margin: 15px auto 30px;
    padding: 0;
    display: flex;
    gap: 2%;
    flex-wrap: wrap;
    align-items: stretch;
    max-width: 860px;
    line-height: 1.2em;
}
.article_list ul li {
    list-style: none;
    margin: 0 0 3%;
    padding: 0;
    width: 32%;
    background: #fff;
    box-shadow: rgba(0,0,0,0.2) 2px 2px 4px;
    border-radius: 10px;
    border: 1px solid #8E292C;
}
.article_list ul li a {
    display: block;
    padding: 10px;
    font-size: 14px;
    line-height: 1.4em;
    color: #333;
    text-decoration: none;
    transition: all 0.5s linear;
}
.article_list ul li a figure {
    position: relative;
    padding: 70% 0 0;
    margin: 0;
    height: 0;
    overflow: hidden;
}
.article_list ul li a figure img {
    position: absolute;
    object-fit: cover;
    width: 100%;
    height: 100%;
    left: 50%;
    top: 50%;
    transform: translate(-50%,-50%);
}
.article_list ul li a .article_list_head {
    font-size: 115%;
    line-height: 1.2em;
    font-weight: bold;
    margin: 10px 0 5px;
}
.article_list ul li a p {
    margin: 0;
}
.article_list ul li a:hover {
    opacity: 0.7;
    transition: all 0.2s linear;
}
.article_list ul li a p time {
    display: block;
    font-size: 90%;
    font-weight: bold;
    background: #8E292C;
    color: #fff;
    padding: 3px;
    text-align: center;
    margin: 0 0 5px;
    border-radius: 5px;
    opacity: 0.5;
}
@media (max-width: 768px) {
    .article_list ul {
        gap: 4%;
        margin: 30px 10px;
    }
    .article_list ul li {
        list-style: none;
        width: 48%;
    }
    .article_list ul li a {
        padding: 10px;
    }
}
@media (max-width: 480px) {
    .article_list ul li {
        list-style: none;
        width: 100%;
    }
}
